import React, { useState, useEffect, useMemo } from 'react';
import { ReminderRecord } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

const Reminders: React.FC = () => {
  const [reminders, setReminders] = useState<ReminderRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<'All' | 'GST' | 'IT' | 'Audit'>('All');

  const fetchReminders = async () => {
    setIsLoading(true);
    const data = await mockBackend.getReminders();
    setReminders(data);
    setIsLoading(false);
  };

  useEffect(() => { fetchReminders(); }, []);

  const toggleComplete = async (rem: ReminderRecord) => {
    const updated = { ...rem, isCompleted: !rem.isCompleted };
    await mockBackend.saveReminder(updated);
    setReminders(prev => prev.map(r => r.id === rem.id ? updated : r));
  };

  const filtered = useMemo(() => {
    return reminders.filter(r => filter === 'All' || r.category === filter);
  }, [reminders, filter]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-7xl mx-auto w-full">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-4 shrink-0">
        <div>
           <h2 className="text-3xl font-black text-slate-900 tracking-tight">Compliance Reminders</h2>
           <p className="text-slate-500 font-medium">Firm-wide deadline tracking and task automation.</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
          {['All', 'GST', 'IT', 'Audit'].map(f => (
            <button key={f} onClick={() => setFilter(f as any)}
              className={`px-6 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${filter === f ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>
              {f}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Active Deadlines</h3>
            <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-[10px] font-black">{filtered.filter(r => !r.isCompleted).length} Tasks</span>
          </div>
          <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar">
            {filtered.length === 0 ? (
              <div className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-xs">No tasks in this category</div>
            ) : (
              filtered.map(rem => (
                <div key={rem.id} className={`flex items-center gap-6 p-6 rounded-3xl border-l-4 transition-all hover:translate-x-1 ${
                  rem.isCompleted ? 'bg-slate-50 opacity-60 border-slate-200' : 
                  rem.priority === 'High' ? 'bg-red-50/30 border-red-500' : 'bg-white border-indigo-500 shadow-sm'
                }`}>
                  <button onClick={() => toggleComplete(rem)} className={`h-8 w-8 rounded-full border-2 flex items-center justify-center transition-all ${
                    rem.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-slate-200 bg-white hover:border-indigo-600'
                  }`}>
                    {rem.isCompleted && <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                  </button>
                  <div className="flex-1 min-w-0">
                    <h4 className={`text-lg font-black tracking-tight uppercase ${rem.isCompleted ? 'line-through text-slate-400' : 'text-slate-900'}`}>{rem.title}</h4>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mt-1">{rem.category} • Due {rem.dueDate}</p>
                  </div>
                  <div className="shrink-0 text-right">
                    <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${
                      rem.priority === 'High' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-400'
                    }`}>{rem.priority}</span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-8">
           <div className="rounded-[2.5rem] bg-slate-900 p-10 text-white shadow-2xl relative overflow-hidden">
              <div className="absolute -top-10 -right-10 h-40 w-40 bg-indigo-500/20 rounded-full blur-3xl" />
              <h3 className="text-xl font-black uppercase tracking-tight mb-2">Sync Status</h3>
              <p className="text-slate-400 text-sm font-medium mb-8">Next firm-wide compliance audit in 4 hours.</p>
              <div className="space-y-6">
                 {[
                   { label: 'GST Returns', val: 85 },
                   { label: 'IT Filings', val: 40 },
                   { label: 'Tax Audits', val: 12 }
                 ].map(it => (
                   <div key={it.label} className="space-y-2">
                     <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-400">
                        <span>{it.label}</span>
                        <span>{it.val}%</span>
                     </div>
                     <div className="h-1.5 w-full bg-white/10 rounded-full">
                        <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${it.val}%` }} />
                     </div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default Reminders;

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

const Messenger: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [message, setMessage] = useState('');
  const [search, setSearch] = useState('');

  useEffect(() => {
    mockBackend.getClients().then(data => {
      setClients(data);
      setIsLoading(false);
    });
  }, []);

  const filteredClients = useMemo(() => {
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(search.toLowerCase()) || 
      c.tradeName.toLowerCase().includes(search.toLowerCase())
    );
  }, [clients, search]);

  const toggleAll = () => {
    if (selectedIds.size === filteredClients.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredClients.map(c => c.id)));
    }
  };

  const handleSend = () => {
    const targets = clients.filter(c => selectedIds.has(c.id)).map(c => c.mobile);
    if (targets.length === 0) return alert('Select clients first');

    // In a real app, this would loop or use a bulk API
    const firstMobile = targets[0];
    const url = `https://api.whatsapp.com/send?phone=91${firstMobile}&text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-7xl mx-auto w-full">
      <div className="shrink-0">
        <h2 className="text-3xl font-black text-slate-900 tracking-tight">Bulk Messenger</h2>
        <p className="text-slate-500 font-medium">Broadcast messages to your client vault via WhatsApp.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 flex-1 min-h-0">
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col overflow-hidden">
          <div className="p-6 bg-slate-50 border-b border-slate-100 space-y-4">
             <div className="relative">
                <input type="text" placeholder="Search targets..." value={search} onChange={e => setSearch(e.target.value)}
                  className="w-full bg-white border border-slate-200 rounded-xl py-3 pl-10 pr-4 font-bold text-sm outline-none" />
                <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
             </div>
             <button onClick={toggleAll} className="text-[10px] font-black uppercase text-indigo-600 hover:underline">
               {selectedIds.size === filteredClients.length ? 'Deselect All' : 'Select All Filtered'}
             </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
            {filteredClients.map(c => (
              <button key={c.id} onClick={() => {
                const next = new Set(selectedIds);
                next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                setSelectedIds(next);
              }} className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all ${
                selectedIds.has(c.id) ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-50 text-slate-600 border border-transparent'
              }`}>
                <div className="text-left">
                  <p className="text-sm font-black uppercase truncate max-w-[200px]">{c.tradeName || c.legalName}</p>
                  <p className={`text-[10px] font-bold ${selectedIds.has(c.id) ? 'text-indigo-200' : 'text-slate-400'}`}>+91 {c.mobile}</p>
                </div>
                {selectedIds.has(c.id) && <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-8 flex flex-col">
          <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm p-10 flex flex-col">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4 block">Message Composer</label>
            <textarea 
              value={message}
              onChange={e => setMessage(e.target.value)}
              className="flex-1 w-full bg-slate-50 border border-slate-100 rounded-[2rem] p-8 font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-50 transition-all resize-none"
              placeholder="Type your firm's professional message here..."
            />
            <div className="mt-8 flex items-center justify-between">
               <div className="text-slate-400 text-[10px] font-black uppercase tracking-widest">
                  Targets: <span className="text-indigo-600">{selectedIds.size} Clients</span>
               </div>
               <button onClick={handleSend} className="bg-emerald-600 text-white font-black uppercase tracking-widest px-10 py-5 rounded-2xl shadow-xl hover:bg-slate-900 transition-all flex items-center gap-3">
                 <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
                 Start Broadcast
               </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Messenger;

import React, { useState, useEffect, useMemo } from 'react';
import { PaymentRecord, Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const PaymentReceived: React.FC = () => {
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newPay, setNewPay] = useState<Partial<PaymentRecord>>({ mode: 'Bank Transfer', amount: 0 });

  const fetchAll = async () => {
    setIsLoading(true);
    const [pays, clis] = await Promise.all([mockBackend.getPayments(), mockBackend.getClients()]);
    setPayments(pays);
    setClients(clis);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const client = clients.find(c => c.id === newPay.clientId);
    await mockBackend.savePayment({
      ...newPay,
      clientName: client?.legalName || 'Unknown',
      date: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const totals = useMemo(() => {
    return payments.reduce((acc, p) => acc + (p.amount || 0), 0);
  }, [payments]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in duration-500 h-full flex flex-col space-y-6 max-w-7xl mx-auto w-full">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-4 shrink-0">
        <div>
           <h2 className="text-3xl font-black text-slate-900 tracking-tight">Fee Collections</h2>
           <p className="text-slate-500 font-medium">Log and track professional fees received from clients.</p>
        </div>
        <button onClick={() => setIsModalOpen(true)} className="bg-emerald-600 text-white font-black uppercase tracking-widest px-8 py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all text-xs">
          Log Payment
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 shrink-0">
         <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10"><svg className="h-16 w-16" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 14h-2v-2h2v2zm0-4h-2V7h2v5z"/></svg></div>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Total Collections</p>
            <h4 className="text-3xl font-black">₹{totals.toLocaleString()}</h4>
         </div>
         {['Cash', 'Bank Transfer', 'UPI'].map(mode => (
           <div key={mode} className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
              <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">{mode}</p>
              <h4 className="text-2xl font-black text-slate-900">₹{payments.filter(p => p.mode === mode).reduce((a,c) => a+c.amount, 0).toLocaleString()}</h4>
           </div>
         ))}
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Receipt Details</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Client</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Mode / Ref</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Amount</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {payments.length === 0 ? (
                <tr><td colSpan={4} className="py-24 text-center text-slate-300 font-black uppercase tracking-widest text-xs">No payment records found</td></tr>
              ) : (
                payments.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(pay => (
                  <tr key={pay.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-8 py-6">
                      <p className="text-sm font-black text-slate-900 uppercase">RCPT-{pay.id.substring(4, 10).toUpperCase()}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tight">{pay.date}</p>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-sm font-black text-slate-600 uppercase">{pay.clientName}</p>
                    </td>
                    <td className="px-8 py-6">
                      <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[10px] font-black uppercase tracking-widest">{pay.mode}</span>
                      <p className="text-[10px] font-bold text-indigo-400 uppercase mt-1">Ref: {pay.referenceNo || '---'}</p>
                    </td>
                    <td className="px-8 py-6 text-right">
                       <p className="text-lg font-black text-emerald-600">₹{pay.amount.toLocaleString()}</p>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/50 backdrop-blur-md p-4">
          <form onSubmit={handleSave} className="w-full max-w-md bg-white rounded-[3rem] shadow-2xl p-10 space-y-6 animate-in zoom-in-95">
            <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Log Client Fee</h3>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Client</label>
                <select required className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                  value={newPay.clientId || ''} onChange={e => setNewPay({...newPay, clientId: e.target.value})}>
                  <option value="">Select Target Client</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.legalName}</option>)}
                </select>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Amount Received</label>
                <input type="number" required className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                  value={newPay.amount || ''} onChange={e => setNewPay({...newPay, amount: Number(e.target.value)})} placeholder="₹ 0.00" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Payment Mode</label>
                   <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newPay.mode || 'Bank Transfer'} onChange={e => setNewPay({...newPay, mode: e.target.value as any})}>
                     <option value="Cash">Cash</option>
                     <option value="Bank Transfer">Bank Transfer</option>
                     <option value="UPI">UPI</option>
                     <option value="Cheque">Cheque</option>
                   </select>
                 </div>
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Reference No.</label>
                   <input className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newPay.referenceNo || ''} onChange={e => setNewPay({...newPay, referenceNo: e.target.value})} placeholder="TXN ID / CHQ NO" />
                 </div>
              </div>
            </div>
            <div className="flex gap-4 pt-6">
               <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-5 text-slate-500 font-black uppercase tracking-widest text-[11px] border border-slate-100 rounded-2xl">Cancel</button>
               <button type="submit" className="flex-[2] bg-emerald-600 text-white font-black uppercase tracking-widest text-[11px] py-5 rounded-2xl shadow-xl hover:bg-slate-900 transition-all">Record Collection</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default PaymentReceived;

import React, { useState, useEffect } from 'react';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

const Trash: React.FC = () => {
  const [trashItems, setTrashItems] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Note: Simulation of trash using a local key as mockBackend doesn't explicitly store deleted clients
  const fetchTrash = async () => {
    setIsLoading(true);
    const saved = localStorage.getItem('clientify_vault_trash');
    setTrashItems(saved ? JSON.parse(saved) : []);
    setIsLoading(false);
  };

  useEffect(() => { fetchTrash(); }, []);

  const clearTrash = () => {
    if (confirm('Permanently purge all items from vault trash? This action is irreversible.')) {
      localStorage.removeItem('clientify_vault_trash');
      setTrashItems([]);
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-7xl mx-auto w-full">
      <div className="flex items-center justify-between shrink-0">
        <div>
           <h2 className="text-3xl font-black text-slate-900 tracking-tight">Vault Trash</h2>
           <p className="text-slate-500 font-medium">Deleted records are retained here for 30 days before permanent purging.</p>
        </div>
        <button onClick={clearTrash} disabled={trashItems.length === 0} className="bg-red-600 text-white font-black uppercase tracking-widest px-8 py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all text-xs disabled:opacity-30 disabled:shadow-none">
          Empty Trash
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Record Identity</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Category</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Deleted Date</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {trashItems.length === 0 ? (
                <tr><td colSpan={4} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">Vault trash is empty</td></tr>
              ) : (
                trashItems.map((item, idx) => (
                  <tr key={idx} className="hover:bg-red-50/20 transition-colors">
                    <td className="px-8 py-6">
                      <p className="text-sm font-black text-slate-900 uppercase">{item.legalName || item.title || 'Unknown Record'}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tight">ID: {item.id}</p>
                    </td>
                    <td className="px-8 py-6">
                       <span className="px-3 py-1 bg-slate-100 text-slate-500 rounded-lg text-[10px] font-black uppercase tracking-widest">{item.gstProfile ? 'GST CLIENT' : item.itProfile ? 'IT CLIENT' : 'RECORD'}</span>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-sm font-black text-slate-600">May 12, 2025</p>
                    </td>
                    <td className="px-8 py-6 text-right">
                       <button className="text-[10px] font-black uppercase text-indigo-600 hover:underline">Restore</button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

