                            </button>
                         </div>
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      <FoodLicensesForm 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSave={async (data) => {
          await mockBackend.saveFoodLicense(data);
          setIsFormOpen(false);
          fetchRecords();
        }} 
        initialData={selectedRecord} 
      />
    </div>
  );
};

