import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, MiscWorkRecord } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

interface UnifiedDeadline {
  id: string;
  title: string;
  client: string;
  date: string;
  category: 'NOTICE' | 'APPEAL' | 'TRIBUNAL' | 'HIGHCOURT' | 'MISC WORK';
  priority: 'High' | 'Medium' | 'Low';
  status: string;
  origin: 'litigation' | 'work';
}

const Reminders: React.FC = () => {
  const [deadlines, setDeadlines] = useState<UnifiedDeadline[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<'All' | 'Litigation' | 'Misc Work'>('All');

  const fetchUnifiedData = async () => {
    setIsLoading(true);
    try {
      const [litigation, work] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getMiscWork()
      ]);

      const mappedLit: UnifiedDeadline[] = litigation
        .filter(r => r.status === 'Pending')
        .map(r => ({
          id: r.id,
          title: `${r.category} - ${r.section ? `U/s ${r.section}` : r.referenceNo}`,
          client: r.clientName,
          date: r.dueDate,
          category: r.category.toUpperCase() as any,
          priority: 'High',
          status: 'Response Due',
          origin: 'litigation'
        }));

      const mappedWork: UnifiedDeadline[] = work
        .filter(r => r.status !== 'Completed')
        .map(r => ({
          id: r.id,
          title: r.description,
          client: r.clientName,
          date: r.completionDate || r.startDate,
          category: 'MISC WORK',
          priority: 'Medium',
          status: r.status,
          origin: 'work'
        }));

      const combined = [...mappedLit, ...mappedWork].sort((a, b) => 
        new Date(a.date).getTime() - new Date(b.date).getTime()
      );

      setDeadlines(combined);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchUnifiedData();
  }, []);

  const filtered = useMemo(() => {
    if (filter === 'All') return deadlines;
    if (filter === 'Litigation') return deadlines.filter(d => d.origin === 'litigation');
    return deadlines.filter(d => d.origin === 'work');
  }, [deadlines, filter]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-7xl mx-auto w-full">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-4 shrink-0">
        <div>
           <h2 className="text-3xl font-black text-slate-900 tracking-tight leading-none">Critical Deadlines</h2>
           <p className="text-slate-500 font-medium mt-2">Tracking Litigation responses and active Miscellaneous work.</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
          {['All', 'Litigation', 'Misc Work'].map(f => (
            <button key={f} onClick={() => setFilter(f as any)}
              className={`px-6 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${filter === f ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>
              {f}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Active Pipeline</h3>
            <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-[10px] font-black">{filtered.length} Items</span>
          </div>
          <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar">
            {filtered.length === 0 ? (
              <div className="py-20 text-center flex flex-col items-center">
                <svg className="h-16 w-16 text-slate-200 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                <p className="text-slate-300 font-black uppercase tracking-widest text-xs">All matters are up-to-date</p>
              </div>
            ) : (
              filtered.map(item => {
                const isOverdue = new Date(item.date) < new Date();
                return (
                  <div key={item.id} className={`flex items-center gap-6 p-6 rounded-3xl border-l-4 transition-all hover:translate-x-1 bg-white border-slate-100 shadow-sm ${
                    isOverdue ? 'border-l-red-500' : 'border-l-indigo-500'
                  }`}>
                    <div className={`h-12 w-12 rounded-2xl flex items-center justify-center shrink-0 ${
                      item.origin === 'litigation' ? 'bg-amber-50 text-amber-600' : 'bg-blue-50 text-blue-600'
                    }`}>
                      {item.origin === 'litigation' ? (
