                       </div>
                    </td>
                    <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-4 py-5">
                       <p className={`text-[12px] font-black uppercase truncate ${selectedIds.has(c.id) ? 'text-indigo-600' : 'text-slate-900'}`} title={c.tradeName}>{c.tradeName || '---'}</p>
                    </td>
                    <td className="px-4 py-5">
                       <p className="text-[11px] font-bold text-slate-400 uppercase truncate" title={c.legalName}>{c.legalName}</p>
                    </td>
                    <td className="px-4 py-5">
                       <span className="text-[11px] font-black text-slate-600 font-mono tracking-widest uppercase">{c.gstProfile?.gstin || c.itProfile?.pan}</span>
                    </td>
                    <td className="px-4 py-5 text-[12px] font-black text-slate-600 tracking-wider">+91 {c.mobile}</td>
                    <td className="px-4 py-5 text-center">
                       <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-widest ${c.gstProfile ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}>
                          {c.gstProfile ? 'GST' : 'IT'}
                       </span>
                    </td>
                    <td className="px-4 py-5 text-right whitespace-nowrap">
                       <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest ${c.status.includes('Active') ? 'text-green-500' : 'text-slate-300'}`}>
                          {c.status.includes('Active') ? 'Online' : 'Inact.'}
                       </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Message Composer Modal */}
      {isComposerOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-3xl bg-white rounded-[3rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden animate-in zoom-in-95">
              <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between shrink-0">
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Broadcast Hub</h3>
                    <p className="text-slate-500 text-sm font-medium mt-1">Preparing message for {selectedIds.size} selected entities.</p>
                 </div>
                 <button onClick={() => setIsComposerOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100">
                    <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
                 </button>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar">
                 <section>
                    <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4 ml-1">Smart Templates</h4>
                    <div className="flex flex-wrap gap-2">
                       {TEMPLATES.map(t => (
                         <button 
                           key={t.id} 
                           onClick={() => applyTemplate(t.text)}
                           className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                         >
                           {t.label}
                         </button>
                       ))}
                    </div>
                 </section>

                 <section className="flex-1 flex flex-col">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4 ml-1">Message Content</label>
                    <textarea 
                      value={message}
                      onChange={e => setMessage(e.target.value)}
                      className="w-full flex-1 min-h-[250px] bg-slate-50 border border-slate-200 rounded-[2rem] p-8 font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all resize-none"
                      placeholder="Type your message here..."
                    />
                 </section>
              </div>

              <div className="p-10 border-t border-slate-100 bg-slate-50/50 flex items-center justify-between shrink-0">
                 <div className="flex items-center gap-3">
                    <div className="h-12 w-12 rounded-2xl bg-white border border-slate-200 flex items-center justify-center shadow-sm">
                       <svg className="h-6 w-6 text-emerald-500" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
                    </div>
                    <div>
                       <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">WhatsApp Multi-Send</p>
                       <p className="text-xs font-bold text-slate-900 uppercase">Routing via Browser Intent</p>
                    </div>
                 </div>
                 <button 
                   onClick={handleSend}
                   disabled={!message.trim()}
                   className="bg-emerald-600 text-white font-black uppercase tracking-[0.2em] px-12 h-16 rounded-2xl shadow-xl hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-3 disabled:opacity-30 disabled:shadow-none"
                 >
                   Deploy Broadcast
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Messenger;

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

const TEMPLATES = [
  { id: 'data', label: 'Data Request', text: "Dear {{NAME}} ({{GSTIN}}),\n\nPlease provide your purchase and sale data for the current month for GST filing.\n\nThanks,\nVault Management Team" },
  { id: 'done', label: 'Filing Done', text: "Dear {{NAME}} ({{GSTIN}}),\n\nYour GST return for the current period has been successfully filed. The acknowledgment will be shared shortly.\n\nRegards,\nVault Management Team" },
  { id: 'pay', label: 'Payment Reminder', text: "Dear {{NAME}} ({{GSTIN}}),\n\nThis is a gentle reminder regarding the outstanding professional fees. Kindly settle the same at your earliest convenience.\n\nThank you,\nVault Management Team" },
  { id: 'meet', label: 'Custom Alert', text: "Important Notice for {{NAME}} ({{GSTIN}}):\n\n[TYPE CUSTOM MESSAGE HERE]\n\nRegards,\nVault Management Team" }
];

const Messenger: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [templateText, setTemplateText] = useState('');
  const [search, setSearch] = useState('');

  // UI States
  const [isComposerOpen, setIsComposerOpen] = useState(false);
  const [isQueueActive, setIsQueueActive] = useState(false);
  const [queueIndex, setQueueIndex] = useState(0);

  useEffect(() => {
    mockBackend.getClients().then(data => {
      setClients(data);
      setIsLoading(false);
    });
  }, []);

  const filteredClients = useMemo(() => {
    const s = search.toLowerCase();
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      c.tradeName.toLowerCase().includes(s) ||
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s))
    );
  }, [clients, search]);

  const selectedClients = useMemo(() => {
    return clients.filter(c => selectedIds.has(c.id));
  }, [clients, selectedIds]);

  const toggleAll = () => {
    if (selectedIds.size === filteredClients.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredClients.map(c => c.id)));
    }
  };

  const toggleClient = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  // Logic to replace placeholders with actual client data
  const formatMessage = (rawText: string, client: Client) => {
    let text = rawText;
    const name = client.tradeName || client.legalName;
    const gstin = client.gstProfile?.gstin || "N/A";
    text = text.replace(/{{NAME}}/g, name);
    text = text.replace(/{{GSTIN}}/g, gstin);
    return text;
  };

  const startBroadcast = () => {
    if (selectedIds.size === 0) return;
    setQueueIndex(0);
    setIsQueueActive(true);
    setIsComposerOpen(false);
  };

  const processNextInQueue = () => {
    const client = selectedClients[queueIndex];
    if (!client) return;

    const personalizedMsg = formatMessage(templateText, client);
    const url = `https://api.whatsapp.com/send?phone=91${client.mobile}&text=${encodeURIComponent(personalizedMsg)}`;
    window.open(url, '_blank');

    if (queueIndex < selectedClients.length - 1) {
      setQueueIndex(queueIndex + 1);
    } else {
      // Finished
      setTimeout(() => {
        alert("Broadcast Sequence Completed!");
        setIsQueueActive(false);
        setSelectedIds(new Set());
      }, 500);
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      {/* Summary Bar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Vault</p>
            <p className="text-xl font-black text-slate-900 leading-none">{clients.length}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">Targets</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{selectedIds.size}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search Trade Name or GSTIN..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex gap-2 shrink-0">
          <button 
            onClick={toggleAll}
            className="px-6 h-11 border border-slate-200 text-slate-500 font-black uppercase tracking-widest text-[10px] rounded-xl hover:bg-slate-50 transition-all"
          >
            {selectedIds.size === filteredClients.length ? 'Deselect All' : 'Select All'}
          </button>
          <button 
            disabled={selectedIds.size === 0}
            onClick={() => setIsComposerOpen(true)}
            className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 disabled:opacity-30"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
            Compose ({{count: selectedIds.size}})
          </button>
        </div>
      </div>

      {/* Main Table Matrix */}
      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px] text-center">Sel.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[70px]">S.No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[260px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[200px]">GSTIN</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px]">Mobile No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] text-center">Filing Type</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[100px]">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((c, idx) => (
                <tr 
                  key={c.id} 
                  onClick={() => toggleClient(c.id)}
                  className={`cursor-pointer transition-all group ${selectedIds.has(c.id) ? 'bg-indigo-50/50' : 'hover:bg-slate-50/50'}`}
                >
                  <td className="px-4 py-5 text-center">
                     <div className={`h-5 w-5 mx-auto rounded-md border-2 transition-all flex items-center justify-center ${selectedIds.has(c.id) ? 'bg-indigo-600 border-indigo-600' : 'border-slate-200 bg-white group-hover:border-indigo-400'}`}>
                        {selectedIds.has(c.id) && <svg className="h-3 w-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>}
                     </div>
                  </td>
                  <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                  <td className="px-4 py-5">
                     <p className={`text-[12px] font-black uppercase truncate ${selectedIds.has(c.id) ? 'text-indigo-600' : 'text-slate-900'}`}>{c.tradeName || c.legalName}</p>
                  </td>
                  <td className="px-4 py-5 font-black text-slate-600 font-mono tracking-widest text-[11px] uppercase">{c.gstProfile?.gstin || 'N/A'}</td>
                  <td className="px-4 py-5 font-black text-slate-600 text-[12px] tracking-wider">+91 {c.mobile}</td>
                  <td className="px-4 py-5 text-center">
                     <span className="px-2 py-0.5 bg-slate-50 text-slate-400 rounded text-[9px] font-black uppercase tracking-widest">{c.gstProfile?.regType || 'IT'}</span>
                  </td>
                  <td className="px-4 py-5 text-right whitespace-nowrap">
                     <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest ${c.status.includes('Active') ? 'text-green-500' : 'text-slate-300'}`}>
                        {c.status.includes('Active') ? 'Active' : 'Inact.'}
                     </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* STEP 1: Composer Modal */}
      {isComposerOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-3xl bg-white rounded-[3rem] shadow-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95">
              <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between">
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Prepare Broadcast</h3>
                    <p className="text-slate-500 text-sm font-medium mt-1">Drafting for {selectedIds.size} clients.</p>
                 </div>
                 <button onClick={() => setIsComposerOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar">
                 <section>
                    <div className="flex items-center justify-between mb-4">
                       <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 ml-1">Select Smart Template</h4>
                       <div className="flex gap-2">
                          <span className="text-[9px] bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded font-black">{'{{NAME}}'}</span>
                          <span className="text-[9px] bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded font-black">{'{{GSTIN}}'}</span>
                       </div>
                    </div>
                    <div className="flex flex-wrap gap-2">
                       {TEMPLATES.map(t => (
                         <button key={t.id} onClick={() => setTemplateText(t.text)}
                           className="px-4 py-2 bg-slate-50 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all border border-slate-100 shadow-sm">
                           {t.label}
                         </button>
                       ))}
                    </div>
                 </section>

                 <section className="flex-1 flex flex-col">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4 ml-1">Master Draft</label>
                    <textarea 
                      value={templateText}
                      onChange={e => setTemplateText(e.target.value)}
                      className="w-full flex-1 min-h-[250px] bg-slate-50 border border-slate-200 rounded-[2rem] p-8 font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all resize-none"
                      placeholder="Use {{NAME}} and {{GSTIN}} to personalize your message..."
                    />
                 </section>
              </div>

              <div className="p-10 border-t border-slate-100 bg-slate-50/50 flex justify-end">
                 <button 
                   onClick={startBroadcast}
                   disabled={!templateText.trim()}
                   className="bg-indigo-600 text-white font-black uppercase tracking-[0.2em] px-12 h-16 rounded-2xl shadow-xl hover:bg-slate-900 transition-all disabled:opacity-30"
                 >
                   Initialise Queue
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* STEP 2: Queue Engine Modal */}
      {isQueueActive && selectedClients[queueIndex] && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/80 backdrop-blur-xl p-4 animate-in fade-in duration-300">
           <div className="w-full max-w-xl bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-slate-900 p-8 text-white">
                 <div className="flex items-center justify-between mb-6">
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">Broadcast In Progress</span>
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Target {queueIndex + 1} of {selectedClients.length}</span>
                 </div>
                 <div className="flex items-center gap-5">
                    <div className="h-16 w-16 rounded-2xl bg-indigo-600 flex items-center justify-center text-2xl font-black shadow-lg">
                       {(queueIndex + 1)}
                    </div>
                    <div className="min-w-0 flex-1">
                       <h3 className="text-xl font-black uppercase truncate">{selectedClients[queueIndex].tradeName || selectedClients[queueIndex].legalName}</h3>
                       <p className="text-indigo-400 font-mono tracking-widest text-xs mt-1 uppercase">{selectedClients[queueIndex].gstProfile?.gstin || 'NO GSTIN'}</p>
                    </div>
                 </div>
                 {/* Progress Bar */}
                 <div className="mt-8 h-1.5 w-full bg-white/10 rounded-full overflow-hidden">
                    <div className="h-full bg-indigo-500 transition-all duration-500" style={{ width: `${((queueIndex + 1) / selectedClients.length) * 100}%` }} />
                 </div>
              </div>

              <div className="p-10 space-y-6">
                 <div className="bg-slate-50 border border-slate-100 rounded-2xl p-6">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Live Message Preview</p>
                    <div className="text-slate-700 font-bold whitespace-pre-wrap leading-relaxed text-sm">
                       {formatMessage(templateText, selectedClients[queueIndex])}
                    </div>
                 </div>

                 <div className="flex gap-4">
                    <button onClick={() => setIsQueueActive(false)} className="flex-1 py-5 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-red-500 transition-colors">Abort</button>
                    <button 
                      onClick={processNextInQueue}
                      className="flex-[2] bg-emerald-600 text-white font-black uppercase tracking-[0.2em] py-5 rounded-2xl shadow-xl hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-3"
                    >
