import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

const TEMPLATES = [
  { id: 'data', label: 'Data Request', text: "Dear {{NAME}} ({{GSTIN}}),\n\nPlease provide your purchase and sale data for the current month for GST filing.\n\nThanks,\nVault Management Team" },
  { id: 'done', label: 'Filing Done', text: "Dear {{NAME}} ({{GSTIN}}),\n\nYour GST return for the current period has been successfully filed. The acknowledgment will be shared shortly.\n\nRegards,\nVault Management Team" },
  { id: 'pay', label: 'Payment Reminder', text: "Dear {{NAME}} ({{GSTIN}}),\n\nThis is a gentle reminder regarding the outstanding professional fees. Kindly settle the same at your earliest convenience.\n\nThank you,\nVault Management Team" },
  { id: 'meet', label: 'Custom Alert', text: "Important Notice for {{NAME}} ({{GSTIN}}):\n\n[TYPE CUSTOM MESSAGE HERE]\n\nRegards,\nVault Management Team" }
];

const Messenger: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [templateText, setTemplateText] = useState('');
  const [search, setSearch] = useState('');

  // UI States
  const [isComposerOpen, setIsComposerOpen] = useState(false);
  const [isQueueActive, setIsQueueActive] = useState(false);
  const [queueIndex, setQueueIndex] = useState(0);

  useEffect(() => {
    mockBackend.getClients().then(data => {
      setClients(data);
      setIsLoading(false);
    });
  }, []);

  const filteredClients = useMemo(() => {
    const s = search.toLowerCase();
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      c.tradeName.toLowerCase().includes(s) ||
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s))
    );
  }, [clients, search]);

  const selectedClients = useMemo(() => {
    return clients.filter(c => selectedIds.has(c.id));
  }, [clients, selectedIds]);

  const toggleAll = () => {
    if (selectedIds.size === filteredClients.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredClients.map(c => c.id)));
    }
  };

  const toggleClient = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  // Logic to replace placeholders with actual client data
  const formatMessage = (rawText: string, client: Client) => {
    let text = rawText;
    const name = client.tradeName || client.legalName;
    const gstin = client.gstProfile?.gstin || "N/A";
    text = text.replace(/{{NAME}}/g, name);
    text = text.replace(/{{GSTIN}}/g, gstin);
    return text;
  };

  const startBroadcast = () => {
    if (selectedIds.size === 0) return;
    setQueueIndex(0);
    setIsQueueActive(true);
    setIsComposerOpen(false);
  };

  const processNextInQueue = () => {
    const client = selectedClients[queueIndex];
    if (!client) return;

    const personalizedMsg = formatMessage(templateText, client);
    const url = `https://api.whatsapp.com/send?phone=91${client.mobile}&text=${encodeURIComponent(personalizedMsg)}`;
    window.open(url, '_blank');

    if (queueIndex < selectedClients.length - 1) {
      setQueueIndex(queueIndex + 1);
    } else {
      // Finished
      setTimeout(() => {
        alert("Broadcast Sequence Completed!");
