import React, { useState, useEffect, useMemo } from 'react';
import { InvoiceRecord, Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const Invoices: React.FC = () => {
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [newInv, setNewInv] = useState<Partial<InvoiceRecord>>({ status: 'Draft', amount: 0, taxAmount: 0 });

  const fetchAll = async () => {
    setIsLoading(true);
    const [invs, clis] = await Promise.all([mockBackend.getInvoices(), mockBackend.getClients()]);
    setInvoices(invs);
    setClients(clis);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const client = clients.find(c => c.id === newInv.clientId);
    const total = (newInv.amount || 0) + (newInv.taxAmount || 0);
    await mockBackend.saveInvoice({
      ...newInv,
      clientName: client?.legalName || 'Unknown',
      totalAmount: total,
      date: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const filteredInvoices = useMemo(() => {
    const s = search.toLowerCase();
    return invoices.filter(i => 
      i.invoiceNo.toLowerCase().includes(s) || 
      i.clientName.toLowerCase().includes(s)
    ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [invoices, search]);

  const stats = useMemo(() => {
    return {
      total: invoices.length,
      paid: invoices.filter(i => i.status === 'Paid').length,
      pending: invoices.filter(i => i.status !== 'Paid' && i.status !== 'Cancelled').length,
      totalValue: invoices.reduce((acc, i) => acc + (i.status === 'Paid' ? i.totalAmount : 0), 0)
    };
  }, [invoices]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Invoices</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">Settled</p>
            <p className="text-xl font-black text-emerald-600 leading-none">{stats.paid}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">Pending</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{stats.pending}</p>
          </div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search by Invoice No or Client..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          New Invoice
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[70px]">S.No.</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Invoice No</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Entity Name</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Amount Details</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[140px]">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredInvoices.length === 0 ? (
                <tr><td colSpan={6} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No billing records found</td></tr>
              ) : (
                filteredInvoices.map((inv, idx) => (
                  <tr key={inv.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-6 py-6 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-6 py-6 font-black text-slate-900 text-[12px] uppercase">{inv.invoiceNo}</td>
                    <td className="px-6 py-6 font-black text-slate-700 text-[12px] uppercase truncate">{inv.clientName}</td>
                    <td className="px-6 py-6 font-bold text-slate-500 text-[11px] uppercase">{inv.date.split('-').reverse().join('-')}</td>
                    <td className="px-6 py-6">
                      <p className="text-[12px] font-black text-indigo-600 leading-none">₹{inv.totalAmount.toLocaleString()}</p>
                      <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">Tax: ₹{inv.taxAmount.toLocaleString()}</p>
                    </td>
                    <td className="px-6 py-6 text-right">
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${
                        inv.status === 'Paid' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                        inv.status === 'Overdue' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-slate-50 text-slate-400 border-slate-100'
                      }`}>{inv.status}</span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
