            <div className="flex items-center justify-between shrink-0">
               <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Generate Bill</h3>
               <button type="button" onClick={() => setIsModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Select Client</label>
                <select required className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none focus:ring-4 focus:ring-indigo-50 transition-all uppercase"
                  value={newInv.clientId || ''} onChange={e => setNewInv({...newInv, clientId: e.target.value})}>
                  <option value="">-- Choose Client --</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.legalName}</option>)}
                </select>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Invoice Reference</label>
                <input required className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none focus:ring-4 focus:ring-indigo-50 transition-all"
                  value={newInv.invoiceNo || ''} onChange={e => setNewInv({...newInv, invoiceNo: e.target.value.toUpperCase()})} placeholder="E.G. INV/2025/001" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Base Fee</label>
                   <input required type="number" className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newInv.amount || ''} onChange={e => setNewInv({...newInv, amount: Number(e.target.value)})} placeholder="0.00" />
                 </div>
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Tax / GST</label>
                   <input required type="number" className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newInv.taxAmount || ''} onChange={e => setNewInv({...newInv, taxAmount: Number(e.target.value)})} placeholder="0.00" />
                 </div>
              </div>
            </div>
