import React, { useState, useEffect, useMemo } from 'react';
import { PaymentRecord, Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const PaymentReceived: React.FC = () => {
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [newPay, setNewPay] = useState<Partial<PaymentRecord>>({ mode: 'Bank Transfer', amount: 0 });

  const fetchAll = async () => {
    setIsLoading(true);
    const [pays, clis] = await Promise.all([mockBackend.getPayments(), mockBackend.getClients()]);
    setPayments(pays);
    setClients(clis);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const client = clients.find(c => c.id === newPay.clientId);
    await mockBackend.savePayment({
      ...newPay,
      clientName: client?.legalName || 'Unknown',
      date: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const filteredPayments = useMemo(() => {
    const s = search.toLowerCase();
    return payments.filter(p => 
      p.clientName.toLowerCase().includes(s) || 
      (p.referenceNo && p.referenceNo.toLowerCase().includes(s))
    ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [payments, search]);

  const stats = useMemo(() => {
    return {
      total: filteredPayments.reduce((acc, p) => acc + (p.amount || 0), 0),
      count: filteredPayments.length,
      upi: filteredPayments.filter(p => p.mode === 'UPI').reduce((acc, p) => acc + (p.amount || 0), 0),
      bank: filteredPayments.filter(p => p.mode === 'Bank Transfer').reduce((acc, p) => acc + (p.amount || 0), 0),
    };
  }, [filteredPayments]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Fee</p>
            <p className="text-xl font-black text-slate-900 leading-none">₹{stats.total.toLocaleString()}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">UPI Net</p>
            <p className="text-xl font-black text-emerald-600 leading-none">₹{stats.upi.toLocaleString()}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">Bank Net</p>
            <p className="text-xl font-black text-indigo-600 leading-none">₹{stats.bank.toLocaleString()}</p>
          </div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search by Client or Ref No..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-emerald-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button onClick={() => setIsModalOpen(true)} className="bg-emerald-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Record Fee
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[70px]">S.No.</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Entity Name</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Mode</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[220px]">Reference / TXN</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[140px]">Amount</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredPayments.length === 0 ? (
                <tr><td colSpan={6} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No payment records found</td></tr>
              ) : (
                filteredPayments.map((pay, idx) => (
                  <tr key={pay.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-6 py-6 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-6 py-6 font-black text-slate-900 text-[12px] uppercase truncate" title={pay.clientName}>{pay.clientName}</td>
                    <td className="px-6 py-6 font-bold text-slate-500 text-[11px] uppercase">{pay.date.split('-').reverse().join('-')}</td>
                    <td className="px-6 py-6">
                      <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[10px] font-black uppercase tracking-widest">{pay.mode}</span>
                    </td>
                    <td className="px-6 py-6 font-black text-indigo-600 text-[11px] uppercase tracking-wider">{pay.referenceNo || '---'}</td>
                    <td className="px-6 py-6 text-right">
                      <p className="text-base font-black text-emerald-600">₹{pay.amount.toLocaleString()}</p>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/50 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <form onSubmit={handleSave} className="w-full max-w-md bg-white rounded-[3rem] shadow-2xl p-10 space-y-6 animate-in zoom-in-95">
            <div className="flex items-center justify-between shrink-0">
               <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Record Payment</h3>
               <button type="button" onClick={() => setIsModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Client</label>
                <select required className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none focus:ring-4 focus:ring-emerald-100 transition-all uppercase"
                  value={newPay.clientId || ''} onChange={e => setNewPay({...newPay, clientId: e.target.value})}>
                  <option value="">-- Choose Client --</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.legalName}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Mode</label>
                   <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newPay.mode || 'Bank Transfer'} onChange={e => setNewPay({...newPay, mode: e.target.value as any})}>
                     <option value="Cash">Cash</option>
                     <option value="Bank Transfer">Bank Transfer</option>
                     <option value="UPI">UPI</option>
                     <option value="Cheque">Cheque</option>
                   </select>
                 </div>
                 <div>
                   <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">Amount</label>
                   <input required type="number" className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none"
                     value={newPay.amount || ''} onChange={e => setNewPay({...newPay, amount: Number(e.target.value)})} placeholder="0.00" />
                 </div>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block ml-1">TXN / Reference No.</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold outline-none uppercase"
                  value={newPay.referenceNo || ''} onChange={e => setNewPay({...newPay, referenceNo: e.target.value.toUpperCase()})} placeholder="OPTIONAL" />
              </div>
            </div>
            <div className="flex gap-4 pt-6">
               <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-5 text-slate-500 font-black uppercase text-[11px] border border-slate-100 rounded-2xl">Cancel</button>
               <button type="submit" className="flex-[2] bg-emerald-600 text-white font-black uppercase text-[11px] py-5 rounded-2xl shadow-xl hover:bg-slate-900 transition-all">Submit Entry</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

