import React, { useState, useEffect, useMemo } from 'react';
import { Client, InvoiceRecord, InvoiceLineItem } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const TAX_RATES = [0, 5, 12, 18, 28];

const AddInvoice: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [invoiceNo, setInvoiceNo] = useState('');

  // Form State
  const [selectedClientId, setSelectedClientId] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMiscClient, setIsMiscClient] = useState(false);
  const [invDate, setInvDate] = useState(new Date().toISOString().split('T')[0]);

  // Misc Client Fields
  const [miscName, setMiscName] = useState('');
  const [miscMobile, setMiscMobile] = useState('');
  const [miscAddress, setMiscAddress] = useState('');

  const [items, setItems] = useState<InvoiceLineItem[]>([
    { id: '1', description: '', quantity: 1, rate: 0, taxRate: 18, amount: 0 }
  ]);
  const [status, setStatus] = useState<InvoiceRecord['status']>('Draft');

  useEffect(() => {
    const init = async () => {
      const [clis, nextNo] = await Promise.all([
        mockBackend.getClients(),
        mockBackend.generateNextInvoiceNo()
      ]);
      setClients(clis);
      setInvoiceNo(nextNo);
      setIsLoading(false);
    };
    init();
  }, []);

  const filteredClients = useMemo(() => {
    if (!searchQuery) return [];
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.tradeName.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [clients, searchQuery]);

  const totals = useMemo(() => {
    const subTotal = items.reduce((acc, item) => acc + (item.rate * item.quantity), 0);
    const totalTax = items.reduce((acc, item) => acc + ((item.rate * item.quantity) * (item.taxRate / 100)), 0);
    return { subTotal, totalTax, grandTotal: subTotal + totalTax };
  }, [items]);

  const addItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', quantity: 1, rate: 0, taxRate: 18, amount: 0 }]);
  };

  const removeItem = (id: string) => {
    if (items.length > 1) setItems(items.filter(i => i.id !== id));
  };

  const updateItem = (id: string, field: keyof InvoiceLineItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        updated.amount = updated.rate * updated.quantity;
        return updated;
      }
      return item;
    }));
  };

  const handleSave = async () => {
    if (!isMiscClient && !selectedClientId) return alert('Please select a client');
    if (isMiscClient && !miscName) return alert('Please enter miscellaneous client name');

    const client = clients.find(c => c.id === selectedClientId);

    // Auto-calculate Due Date (Date + 15 days)
    const dDate = new Date(invDate);
    dDate.setDate(dDate.getDate() + 15);
    const dueDateStr = dDate.toISOString().split('T')[0];

    const record: Partial<InvoiceRecord> = {
      clientId: isMiscClient ? 'misc' : selectedClientId,
      clientName: isMiscClient ? miscName : (client?.legalName || 'Unknown'),
      isMiscClient,
      miscMobile,
      miscAddress,
      invoiceNo,
      date: invDate,
      dueDate: dueDateStr,
      items,
      subTotal: totals.subTotal,
      totalTax: totals.totalTax,
      totalAmount: totals.grandTotal,
      status
    };

    await mockBackend.saveInvoice(record);
    onBack();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-5xl mx-auto w-full overflow-hidden">

      <div className="flex items-center justify-between bg-white p-4 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-all text-slate-400">
            <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">Create Invoice</h2>
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{invoiceNo}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <select value={status} onChange={e => setStatus(e.target.value as any)} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-[10px] font-black uppercase tracking-widest outline-none">
            <option value="Draft">Save as Draft</option>
            <option value="Sent">Mark as Sent</option>
          </select>
          <button onClick={handleSave} className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs">
            Generate Bill
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-y-auto no-scrollbar p-10 space-y-10">

        {/* Client Selector Section */}
        <section>
          <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-indigo-600 mb-6 flex items-center gap-3">Bill To <div className="h-px flex-1 bg-slate-100" /></h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="relative">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">Smart Client Lookup</label>
              <input 
                disabled={isMiscClient}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-indigo-50 transition-all disabled:opacity-30"
                placeholder="Search master records..."
                value={searchQuery}
                onChange={e => { setSearchQuery(e.target.value); setIsDropdownOpen(true); }}
                onFocus={() => setIsDropdownOpen(true)}
              />
              {isDropdownOpen && !isMiscClient && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
                  {filteredClients.length > 0 ? (
                    filteredClients.map(c => (
                      <button key={c.id} onClick={() => { setSelectedClientId(c.id); setSearchQuery(c.legalName); setIsDropdownOpen(false); }}
                        className="w-full text-left px-4 py-3 hover:bg-indigo-50 rounded-xl transition-all">
                        <p className="text-xs font-black text-slate-900 uppercase">{c.legalName}</p>
                        <p className="text-[10px] text-slate-400 font-mono tracking-tight uppercase">{c.gstProfile?.gstin || c.itProfile?.pan || 'NO ID'}</p>
                      </button>
                    ))
                  ) : searchQuery && (
                    <button onClick={() => { setIsMiscClient(true); setIsDropdownOpen(false); setMiscName(searchQuery); }}
                      className="w-full text-center py-4 text-indigo-600 font-black uppercase text-[10px] hover:bg-slate-50 rounded-xl">
                      + Create Miscellaneous Client
                    </button>
                  )}
                </div>
              )}
            </div>

            <div>
               <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">Invoice Date</label>
               <input type="date" value={invDate} onChange={e => setInvDate(e.target.value)} 
                 className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-indigo-50 transition-all uppercase" />
            </div>

            {isMiscClient && (
              <div className="grid grid-cols-1 gap-6 animate-in slide-in-from-right-4 md:col-span-2">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">Misc Client Name</label>
                        <input className="w-full bg-indigo-50/30 border border-indigo-200 rounded-2xl p-4 font-black text-slate-900 outline-none"
                        value={miscName} onChange={e => setMiscName(e.target.value)} />
                    </div>
                    <div>
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">Mobile</label>
                        <div className="flex gap-2">
                            <input className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl p-4 font-black text-slate-900 outline-none"
                            value={miscMobile} onChange={e => setMiscMobile(e.target.value)} />
                            <button onClick={() => { setIsMiscClient(false); setMiscName(''); }} className="px-4 text-[9px] font-black uppercase text-red-500 hover:underline">Reset</button>
                        </div>
                    </div>
                 </div>
                 <div className="col-span-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">Full Address</label>
                    <textarea className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-black text-slate-900 outline-none h-20"
                      value={miscAddress} onChange={e => setMiscAddress(e.target.value)} />
                 </div>
              </div>
            )}
          </div>
        </section>

        {/* Line Items Section */}
        <section>
          <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-indigo-600 mb-6 flex items-center gap-3">Services Matrix <div className="h-px flex-1 bg-slate-100" /></h4>
          <div className="space-y-4">
             {items.map((item, idx) => (
               <div key={item.id} className="grid grid-cols-12 gap-4 items-center bg-slate-50/50 p-4 rounded-2xl border border-slate-100 group animate-in slide-in-from-left-4" style={{ animationDelay: `${idx * 50}ms` }}>
                  <div className="col-span-5">
                    <label className="text-[8px] font-black uppercase text-slate-400 mb-1 block">Description</label>
                    <input className="w-full bg-white border border-slate-200 rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-100"
                      value={item.description} onChange={e => updateItem(item.id, 'description', e.target.value)} placeholder="Consulting Service..." />
                  </div>
                  <div className="col-span-1">
                    <label className="text-[8px] font-black uppercase text-slate-400 mb-1 block">Qty</label>
                    <input type="number" className="w-full bg-white border border-slate-200 rounded-xl p-3 text-xs font-bold outline-none text-center"
                      value={item.quantity} onChange={e => updateItem(item.id, 'quantity', Number(e.target.value))} />
                  </div>
                  <div className="col-span-2">
                    <label className="text-[8px] font-black uppercase text-slate-400 mb-1 block">Rate (₹)</label>
                    <input type="number" className="w-full bg-white border border-slate-200 rounded-xl p-3 text-xs font-black outline-none text-right"
                      value={item.rate} onChange={e => updateItem(item.id, 'rate', Number(e.target.value))} />
                  </div>
                  <div className="col-span-1">
                    <label className="text-[8px] font-black uppercase text-slate-400 mb-1 block">GST %</label>
                    <select className="w-full bg-white border border-slate-200 rounded-xl p-3 text-[10px] font-black outline-none"
                      value={item.taxRate} onChange={e => updateItem(item.id, 'taxRate', Number(e.target.value))}>
                      {TAX_RATES.map(r => <option key={r} value={r}>{r}%</option>)}
                    </select>
                  </div>
                  <div className="col-span-2 text-right">
                    <label className="text-[8px] font-black uppercase text-slate-400 mb-1 block">Total</label>
                    <p className="text-sm font-black text-slate-900">₹{(item.rate * item.quantity).toLocaleString()}</p>
                  </div>
                  <div className="col-span-1 text-right">
                    <button onClick={() => removeItem(item.id)} className="h-10 w-10 flex items-center justify-center text-slate-300 hover:text-red-500 transition-colors">
                      <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    </button>
                  </div>
               </div>
             ))}
             <button onClick={addItem} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-400 hover:border-indigo-600 hover:text-indigo-600 transition-all">+ Add Line Item</button>
          </div>
        </section>

        {/* Calculation Summary Section */}
        <section className="flex justify-end">
           <div className="w-full max-w-sm bg-slate-50 p-8 rounded-[2rem] border border-slate-100 space-y-4">
              <div className="flex justify-between items-center text-slate-500">
                 <span className="text-[10px] font-black uppercase tracking-widest">Sub-Total</span>
                 <span className="text-sm font-black">₹{totals.subTotal.toLocaleString()}</span>
              </div>
              <div className="flex justify-between items-center text-slate-500 border-b border-slate-200 pb-4">
                 <span className="text-[10px] font-black uppercase tracking-widest">Aggregate GST</span>
                 <span className="text-sm font-black">₹{totals.totalTax.toLocaleString()}</span>
              </div>
              <div className="flex justify-between items-center pt-2">
                 <span className="text-xs font-black uppercase tracking-[0.2em] text-indigo-600">Grand Total</span>
                 <span className="text-2xl font-black text-slate-900">₹{totals.grandTotal.toLocaleString()}</span>
              </div>
           </div>
        </section>
      </div>
    </div>
  );
};

export default AddInvoice;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { InvoiceRecord, Client, InvoiceSettings } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

const Invoices: React.FC<{ onViewChange?: (view: string) => void }> = ({ onViewChange }) => {
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Pending' | 'Sent'>('All');
  const [isFilterOpen, setIsFilterOpen] = useState(false);

  const [settings, setSettings] = useState<InvoiceSettings | null>(null);

  // Settlement Modal States
  const [settlingInvoice, setSettlingInvoice] = useState<InvoiceRecord | null>(null);
  const [payDate, setPayDate] = useState(new Date().toISOString().split('T')[0]);
  const [payMode, setPayMode] = useState<'Cash' | 'Online' | 'Cheque'>('Online');
  const [chequeNo, setChequeNo] = useState('');

  // PDF Preview State
  const [previewInvoice, setPreviewInvoice] = useState<InvoiceRecord | null>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    const [invs, sets] = await Promise.all([
      mockBackend.getInvoices(),
      mockBackend.getInvoiceSettings()
    ]);
    setInvoices(invs);
    setSettings(sets);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const filteredInvoices = useMemo(() => {
    const s = search.toLowerCase();
    let list = invoices.filter(i => 
      i.invoiceNo.toLowerCase().includes(s) || 
      i.clientName.toLowerCase().includes(s)
    ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (statusFilter !== 'All') {
      list = list.filter(i => i.status === statusFilter);
    }
    return list;
  }, [invoices, search, statusFilter]);

  const handleReceiveConfirm = async () => {
    if (!settlingInvoice) return;
    await mockBackend.migrateToPayment(settlingInvoice.id, {
      date: payDate,
      mode: payMode,
      chequeNo: payMode === 'Cheque' ? chequeNo : undefined
    });
    setSettlingInvoice(null);
    fetchAll();
  };

  const handleWhatsApp = (inv: InvoiceRecord) => {
    const text = `*Invoice from ${settings?.invoicePrefix || 'Vault'}*\n\nInv No: ${inv.invoiceNo}\nDate: ${inv.date.split('-').reverse().join('-')}\nAmount: ₹${inv.totalAmount.toLocaleString()}\nDue Date: ${inv.dueDate.split('-').reverse().join('-')}\n\nKindly settle the same. Thank you!`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handlePrint = () => {
    const printContent = printRef.current;
    const windowUrl = 'about:blank';
    const uniqueName = new Date().getTime();
    const windowName = 'Print' + uniqueName;
    const printWindow = window.open(windowUrl, windowName, 'left=50000,top=50000,width=0,height=0');

    if (printWindow && printContent) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Invoice - ${previewInvoice?.invoiceNo}</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <style>
              @media print {
                body { padding: 0; margin: 0; }
                .no-print { display: none; }
              }
              body { font-family: sans-serif; }
            </style>
          </head>
          <body onload="window.print();window.close()">
            <div class="p-8">${printContent.innerHTML}</div>
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Bills</p>
            <p className="text-xl font-black text-slate-900 leading-none">{invoices.length}</p>
          </div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search by Invoice No or Client..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex gap-2">
          <div className="relative">
            <button onClick={() => setIsFilterOpen(!isFilterOpen)} className="h-11 px-4 flex items-center gap-2 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-black uppercase text-slate-500 hover:bg-slate-100">
               Filter: {statusFilter} <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isFilterOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white border border-slate-200 rounded-xl shadow-2xl z-50 p-1 animate-in zoom-in-95">
                {['All', 'Pending', 'Sent'].map(f => (
                  <button key={f} onClick={() => { setStatusFilter(f as any); setIsFilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${statusFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                ))}
              </div>
            )}
          </div>
          <button onClick={() => onViewChange?.('admin-invoice-setting')} className="h-11 w-11 flex items-center justify-center bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-all shadow-sm">
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
          </button>
          <button onClick={() => onViewChange?.('admin-add-invoice')} className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Create Invoice
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Inv. No.</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Client</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Service</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Amount</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Due Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-center w-[140px]">Status</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[180px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredInvoices.length === 0 ? (
                <tr><td colSpan={8} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No billing records found</td></tr>
              ) : (
                filteredInvoices.map((inv) => (
                  <tr key={inv.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-6 py-6 font-black text-slate-900 text-[12px] uppercase">{inv.invoiceNo}</td>
                    <td className="px-6 py-6 font-bold text-slate-500 text-[11px] uppercase">{inv.date.split('-').reverse().join('-')}</td>
                    <td className="px-6 py-6 font-black text-slate-700 text-[12px] uppercase truncate">{inv.clientName}</td>
                    <td className="px-6 py-6 text-[11px] font-bold text-slate-400 truncate uppercase">
                      {inv.items?.[0]?.description} {inv.items?.length > 1 ? `(+${inv.items.length - 1})` : ''}
                    </td>
                    <td className="px-6 py-6 font-black text-indigo-600 text-[12px]">₹{inv.totalAmount.toLocaleString()}</td>
                    <td className="px-6 py-6">
                       <p className="text-[11px] font-black text-slate-700 uppercase">{inv.dueDate.split('-').reverse().join('-')}</p>
                    </td>
                    <td className="px-6 py-6 text-center">
                       <select 
                         value={inv.status} 
                         onChange={(e) => {
                           if (e.target.value === 'Paid') {
                             setSettlingInvoice(inv);
                           } else {
                             mockBackend.saveInvoice({...inv, status: e.target.value as any}).then(fetchAll);
                           }
                         }}
                         className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all cursor-pointer ${
                           inv.status === 'Sent' ? 'bg-blue-50 text-blue-600 border-blue-100' : 'bg-slate-50 text-slate-400 border-slate-100'
                         }`}
                       >
                         <option value="Draft">Draft</option>
                         <option value="Sent">Sent</option>
                         <option value="Paid">Receive</option>
                       </select>
                    </td>
                    <td className="px-6 py-6 text-right whitespace-nowrap">
                       <div className="flex items-center justify-end gap-2">
                          <button onClick={() => setPreviewInvoice(inv)} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 transition-all flex items-center justify-center shadow-sm" title="View & Print PDF">
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                          </button>
                          <button onClick={() => handleWhatsApp(inv)} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-emerald-600 transition-all flex items-center justify-center shadow-sm" title="Send via WhatsApp">
                             <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
                          </button>
                       </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* RECEIVE PAYMENT MODAL */}
      {settlingInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Receive Payment</h3>
              <div className="bg-indigo-50 p-4 rounded-xl">
                 <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Settle Invoice</p>
                 <p className="text-sm font-black text-indigo-900">{settlingInvoice.invoiceNo} • ₹{settlingInvoice.totalAmount.toLocaleString()}</p>
              </div>
              <div className="space-y-4">
                 <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block">Payment Date</label>
                    <input type="date" value={payDate} onChange={e => setPayDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold" />
                 </div>
                 <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block">Mode of Payment</label>
                    <select value={payMode} onChange={e => setPayMode(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold">
                       <option value="Online">Online / UPI</option>
                       <option value="Cash">Cash</option>
                       <option value="Cheque">Cheque</option>
                    </select>
                 </div>
                 {payMode === 'Cheque' && (
                    <div className="animate-in slide-in-from-top-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase mb-1.5 block">Cheque Number</label>
                       <input value={chequeNo} onChange={e => setChequeNo(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-black uppercase" placeholder="Enter 6-digit no." />
                    </div>
                 )}
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setSettlingInvoice(null)} className="flex-1 py-4 text-slate-500 font-black uppercase text-[10px] rounded-xl border border-slate-200">Cancel</button>
                 <button onClick={handleReceiveConfirm} className="flex-[2] py-4 bg-emerald-600 text-white font-black uppercase text-[10px] rounded-xl shadow-lg">Confirm Receipt</button>
              </div>
           </div>
        </div>
      )}

      {/* PDF PREVIEW MODAL */}
