    const newRec = { ...data, id: this.generateId('inv'), createdAt: Date.now() } as InvoiceRecord;
    records.push(newRec);
    localStorage.setItem(this.STORAGE_KEY_INVOICES, JSON.stringify(records));
    return newRec;
