      {/* PDF PREVIEW MODAL */}
      {previewInvoice && settings && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/80 backdrop-blur-md p-4 animate-in fade-in overflow-y-auto">
           <div className="bg-white rounded-[1.5rem] shadow-2xl w-full max-w-4xl relative">
              <div className="sticky top-0 right-0 p-4 flex justify-end gap-3 z-50 bg-white/80 backdrop-blur border-b border-slate-100 rounded-t-[1.5rem] no-print">
                 <button onClick={handlePrint} className="bg-indigo-600 text-white font-black uppercase text-[10px] px-6 py-2.5 rounded-lg shadow-lg">Print / Save PDF</button>
                 <button onClick={() => setPreviewInvoice(null)} className="bg-slate-100 text-slate-600 font-black uppercase text-[10px] px-6 py-2.5 rounded-lg">Close</button>
              </div>

              {/* THE ACTUAL INVOICE LAYOUT */}
              <div ref={printRef} className="p-16 bg-white min-h-[1123px] text-slate-900 relative">
                 {/* Header Row */}
                 <div className="flex justify-between items-start border-b-2 border-slate-900 pb-10 mb-10">
                    <div className="space-y-4">
                       {settings.firmLogo && <img src={settings.firmLogo} className="h-20 object-contain" alt="Firm Logo" />}
                       <div>
                          <h1 className="text-3xl font-black uppercase tracking-tight">Invoice</h1>
