                    <td className="px-4 py-6 font-black text-indigo-600 text-[11px] tracking-widest">{pay.chequeNo || '---'}</td>
                    <td className="px-6 py-6 text-right whitespace-nowrap">
                       <div className="flex items-center justify-end gap-2">
                          <button onClick={() => {
