                       </div>
                    </div>
                 </div>

                 {/* Items Table */}
                 <table className="w-full mb-12 relative z-10">
                    <thead>
                       <tr className="bg-slate-900 text-white">
                          <th className="px-4 py-3 text-[10px] font-black uppercase tracking-widest text-left">Description of Services Settled</th>
                          <th className="px-4 py-3 text-[10px] font-black uppercase tracking-widest text-right w-[150px]">Amount Settled</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200 border-b border-slate-200">
                       {previewPayment.originalItems ? (
                         previewPayment.originalItems.map((item, i) => (
                          <tr key={i}>
                             <td className="px-4 py-5 text-sm font-black uppercase">{item.description}</td>
                             <td className="px-4 py-5 text-sm font-black text-right">₹{item.amount.toLocaleString()}</td>
                          </tr>
                         ))
                       ) : (
                        <tr>
                           <td className="px-4 py-5 text-sm font-black uppercase">Consolidated Professional Services</td>
                           <td className="px-4 py-5 text-sm font-black text-right">₹{previewPayment.amount.toLocaleString()}</td>
                        </tr>
                       )}
                    </tbody>
                 </table>

                 {/* Total Summary */}
                 <div className="flex justify-end mb-20 relative z-10">
                    <div className="text-right space-y-3 w-64 bg-emerald-50 p-6 rounded-2xl border border-emerald-100">
                       <div className="flex justify-between text-emerald-800 font-black text-lg uppercase pt-1">
                          <p>Net Received</p>
                          <p>₹{previewPayment.amount.toLocaleString()}</p>
                       </div>
                    </div>
                 </div>

                 {/* Footer */}
                 <div className="flex justify-between items-end relative z-10">
                    <div className="max-w-md">
                       <h4 className="text-[10px] font-black uppercase text-slate-400 mb-2">Acknowledgment:</h4>
                       <p className="text-[10px] font-medium text-slate-400 leading-relaxed uppercase">This is a computer generated payment receipt and serves as a confirmation of funds received against professional services rendered.</p>
                    </div>
                    <div className="text-right">
                       {settings.firmSignature && <img src={settings.firmSignature} className="h-16 ml-auto mb-2 opacity-90 mix-blend-multiply" alt="Signature" />}
                       <p className="text-[10px] font-black uppercase border-t border-slate-900 pt-2 px-4">Finance Department</p>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default PaymentReceived;

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface User {
  id: string;
  username: string;
  user_id: string;
  email_id: string;
  mobile_no?: string;
  firm_name?: string | null;
  gstn?: string | null;
  status: 'online' | 'away' | 'offline';
}

export interface AppState {
  messages: Message[];
  metrics: MetricData[];
  users: User[];
  isConnected: boolean;
  currentUser: User | null;
}

export type ActiveView = string;

export type ClientStatus = 'Active Filing' | 'Case-by-Case' | 'Inactive (Temporary)' | 'Inactive (Closed)' | 'Active' | 'Inactive';
export type GstStatus = 'Active' | 'Suspended' | 'Cancelled';
export type GstRegType = 'Regular' | 'Composition';
export type GstFilingFreq = 'Monthly' | 'Quarterly';
