  async createItem(userId: string, data: any): Promise<any> {
    const allItems = JSON.parse(localStorage.getItem(this.STORAGE_KEY_ITEMS) || '[]');
    const users = this.getUsers();
    const user = users.find((u: any) => u.id === userId);

    const newItem = {
