import React, { useState, useEffect } from 'react';
import Loader from '../../components/Loader';
import { YEARS, MONTHS, FY_QUARTERS } from '../Compliance/GSTReturn/filinglogic/MonthlyFilingLogic';

const MODULES = [
  { id: 'monthly_r1', label: 'GSTR-1 (Monthly)', group: 'GST' },
  { id: 'monthly_r3b', label: 'GSTR-3B (Monthly)', group: 'GST' },
  { id: 'quarterly_iff', label: 'IFF/R1 (Quarterly)', group: 'GST' },
  { id: 'quarterly_r3b', label: 'GSTR-3B (Quarterly)', group: 'GST' },
  { id: 'composition_cmp08', label: 'CMP-08 (Quarterly)', group: 'Composition' },
  { id: 'composition_gstr4', label: 'GSTR-4 (Annual)', group: 'Composition' },
  { id: 'annual_gstr9', label: 'GSTR-9 (Annual)', group: 'GST' },
  { id: 'annual_gstr9c', label: 'GSTR-9C (Annual)', group: 'GST' },
  { id: 'audit_tax', label: 'Tax Audit', group: 'Income Tax' },
  { id: 'itr_return', label: 'ITR Returns', group: 'Income Tax' }
];

const DueDateSetting: React.FC = () => {
  const [selectedYear, setSelectedYear] = useState(YEARS[0]);
  const [selectedPeriod, setSelectedPeriod] = useState(MONTHS[new Date().getMonth()]);
  const [isLoading, setIsLoading] = useState(true);
  const [dates, setDates] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);

  const STORAGE_KEY = 'clientify_global_compliance_dates_v1';

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) setDates(JSON.parse(saved));
    setIsLoading(false);
  }, []);

  const handleDateChange = (moduleId: string, value: string) => {
    const key = `${moduleId}_${selectedYear}_${selectedPeriod}`;
    setDates(prev => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    setIsSaving(true);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(dates));

    // Legacy support: Map these to the individual module keys for immediate update
    // This ensures existing logic in MonthlyFiling etc. still works
    const periodKey = `${selectedYear}_${selectedPeriod}`;

    // R1 Monthly
    const r1Date = dates[`monthly_r1_${periodKey}`];
    if (r1Date) {
       const legacy = JSON.parse(localStorage.getItem('clientify_monthly_due_dates_v1') || '{}');
       localStorage.setItem('clientify_monthly_due_dates_v1', JSON.stringify({...legacy, [periodKey]: r1Date}));
    }

    setTimeout(() => setIsSaving(false), 800);
  };

  const getDateValue = (moduleId: string) => {
    const key = `${moduleId}_${selectedYear}_${selectedPeriod}`;
    return dates[key] || '';
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-5xl mx-auto w-full overflow-hidden">

      <div className="flex items-center justify-between bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6">
           <div>
              <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Compliance Calendar</h2>
              <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Global Due Date Configuration</p>
           </div>
           <div className="h-10 w-[1px] bg-slate-100" />
           <div className="flex gap-2">
              <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)}
                className="bg-slate-50 border-none rounded-xl px-4 py-2 text-[11px] font-black uppercase outline-none cursor-pointer">
                {YEARS.map(y => <option key={y} value={y}>FY {y}</option>)}
              </select>
              <select value={selectedPeriod} onChange={e => setSelectedPeriod(e.target.value)}
                className="bg-slate-50 border-none rounded-xl px-4 py-2 text-[11px] font-black uppercase outline-none cursor-pointer">
                <optgroup label="Monthly">
                  {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
                </optgroup>
                <optgroup label="Quarterly">
                  {FY_QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}
                </optgroup>
                <option value="Annual">ANNUAL / FULL YEAR</option>
              </select>
           </div>
        </div>
        <button onClick={handleSave} disabled={isSaving}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-10 h-12 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs disabled:opacity-50">
          {isSaving ? 'Syncing...' : 'Save Calendar'}
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-y-auto no-scrollbar p-10 space-y-8">
         <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {['GST', 'Composition', 'Income Tax'].map(group => (
               <div key={group} className="space-y-4">
                  <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 border-b border-slate-100 pb-2">{group} Schedule</h3>
                  <div className="space-y-3">
                     {MODULES.filter(m => m.group === group).map(module => (
                        <div key={module.id} className="flex items-center justify-between p-5 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-white hover:shadow-md transition-all group">
                           <span className="text-sm font-black text-slate-700 uppercase">{module.label}</span>
                           <input 
                             type="date" 
                             value={getDateValue(module.id)} 
                             onChange={e => handleDateChange(module.id, e.target.value)}
                             className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-black uppercase outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                           />
                        </div>
                     ))}
                  </div>
               </div>
            ))}
         </div>
      </div>

      <div className="bg-indigo-900 p-8 rounded-[2.5rem] text-white flex items-center justify-between shadow-2xl relative overflow-hidden shrink-0">
         <div className="absolute -top-10 -right-10 h-40 w-40 bg-indigo-500/20 rounded-full blur-3xl" />
         <div>
            <h4 className="text-lg font-black uppercase tracking-tight">System Insight</h4>
            <p className="text-indigo-300 text-sm font-medium mt-1">Dates set here will propagate to all client portfolios and staff dashboards instantly.</p>
         </div>
         <div className="h-12 w-12 rounded-xl bg-white/10 flex items-center justify-center text-indigo-300">
            <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
         </div>
      </div>
    </div>
  );
};

