    setIsLoading(true);
    const [invs, sets] = await Promise.all([
      mockBackend.getInvoices(),
      mockBackend.getInvoiceSettings()
    ]);
    setInvoices(invs);
    setSettings(sets);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

