                          </button>
                       </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Settlement Modal */}
      {settlingInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4">
           <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6">
              <h3 className="text-xl font-black text-slate-900 uppercase">Receive Payment</h3>
              <div className="space-y-4">
                 <input type="date" value={payDate} onChange={e => setPayDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold" />
                 <select value={payMode} onChange={e => setPayMode(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold">
                    <option value="Online">Online Transfer</option>
                    <option value="UPI">UPI / QR</option>
                    <option value="Cash">Cash</option>
                    <option value="Cheque">Cheque</option>
                 </select>
                 {payMode === 'Cheque' && <input value={chequeNo} onChange={e => setChequeNo(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-black" placeholder="Cheque No." />}
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setSettlingInvoice(null)} className="flex-1 py-4 text-slate-500 font-black uppercase text-[10px]">Cancel</button>
                 <button onClick={handleReceiveConfirm} className="flex-[2] py-4 bg-emerald-600 text-white font-black uppercase text-[10px] rounded-xl shadow-lg">Confirm</button>
              </div>
           </div>
        </div>
      )}

      {/* PDF PREVIEW MODAL */}
      {previewInvoice && settings && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/80 backdrop-blur-md p-4 overflow-y-auto">
           <div className="bg-white rounded-[1.5rem] shadow-2xl w-full max-w-5xl relative">
              <div className="sticky top-0 p-4 flex justify-end gap-3 z-50 bg-white/80 backdrop-blur border-b border-slate-100 rounded-t-[1.5rem] no-print">
                 <button onClick={handlePrint} className="bg-indigo-600 text-white font-black uppercase text-[10px] px-6 py-2.5 rounded-lg shadow-lg">Print / Save PDF</button>
                 <button onClick={() => setPreviewInvoice(null)} className="bg-slate-100 text-slate-600 font-black uppercase text-[10px] px-6 py-2.5 rounded-lg">Close</button>
              </div>

              <div ref={printRef} className="bg-white text-slate-900 relative">
                 <!-- The Print Content is constructed inside handlePrint string for complex layout control -->
                 <div class="p-16">
                    <p class="text-center text-slate-300 font-bold uppercase text-[10px] tracking-widest">Generating Secure Preview...</p>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Invoices;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { PaymentRecord, Client, InvoiceSettings } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

interface PaymentReceivedProps {
  onViewChange?: (view: string, extra?: any) => void;
}

const PaymentReceived: React.FC<PaymentReceivedProps> = ({ onViewChange }) => {
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [settings, setSettings] = useState<InvoiceSettings | null>(null);

  const [previewPayment, setPreviewPayment] = useState<PaymentRecord | null>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    const [pays, sets] = await Promise.all([mockBackend.getPayments(), mockBackend.getInvoiceSettings()]);
    setPayments(pays);
    setSettings(sets);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const filteredPayments = useMemo(() => {
    const s = search.toLowerCase();
    return payments.filter(p => 
      p.clientName.toLowerCase().includes(s) || 
      (p.referenceNo && p.referenceNo.toLowerCase().includes(s)) ||
      (p.invoiceNo && p.invoiceNo.toLowerCase().includes(s))
    ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [payments, search]);

  const stats = useMemo(() => {
    return {
      total: filteredPayments.reduce((acc, p) => acc + (p.amount || 0), 0),
      online: filteredPayments.filter(p => p.mode === 'Online' || p.mode === 'UPI' || p.mode === 'Bank Transfer').reduce((acc, p) => acc + (p.amount || 0), 0),
      cheque: filteredPayments.filter(p => p.mode === 'Cheque').reduce((acc, p) => acc + (p.amount || 0), 0),
      cash: filteredPayments.filter(p => p.mode === 'Cash').reduce((acc, p) => acc + (p.amount || 0), 0),
    };
  }, [filteredPayments]);

  const handlePrint = () => {
    if (!previewPayment || !settings) return;

    const windowUrl = 'about:blank';
    const printWindow = window.open(windowUrl, '_blank', 'width=800,height=900');

    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Receipt - ${previewPayment.invoiceNo || 'DIRECT'}</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <style>
              @media print {
                @page { size: A4; margin: 15mm; }
                body { padding: 0; margin: 0; font-family: sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                thead { display: table-header-group; }
                tfoot { display: table-footer-group; }
                tr { break-inside: avoid; }
                .mohar { 
                   position: fixed; top: 40%; left: 50%; transform: translate(-50%, -50%) rotate(-15deg); 
                   border: 6px solid #10b981; border-radius: 50%; opacity: 0.1; width: 300px; height: 300px;
                   display: flex; flex-direction: column; align-items: center; justify-content: center;
                   pointer-events: none; z-index: 0;
                }
              }
            </style>
          </head>
          <body onload="setTimeout(() => { window.print(); window.close(); }, 700)">
            <div class="mohar">
              <p class="text-emerald-600 text-4xl font-black uppercase">PAYMENT</p>
              <p class="text-emerald-600 text-5xl font-black uppercase">RECEIVED</p>
              <div class="h-1 w-64 bg-emerald-600 my-2"></div>
              <p class="text-emerald-600 text-2xl font-black">${previewPayment.date.split('-').reverse().join('-')}</p>
            </div>
            <div class="p-4">
              <table class="w-full">
                <thead>
                  <tr>
                    <td>
                      <div class="border-b-2 border-slate-900 pb-6 mb-6">
                        <div class="flex justify-between items-start">
                          <div class="space-y-4">
                            ${settings.firmLogo ? `<img src="${settings.firmLogo}" class="h-16 object-contain" />` : ''}
                            <h1 class="text-3xl font-black uppercase tracking-tight text-emerald-600">Payment Receipt</h1>
                          </div>
                          <div class="text-right space-y-1">
                            <p class="text-lg font-black uppercase">${settings.firmName}</p>
                            <p class="text-[9px] font-black text-indigo-600 font-mono">GSTIN: ${settings.firmGstin}</p>
                            <p class="text-[9px] font-bold text-slate-500 uppercase whitespace-pre-wrap leading-relaxed">${settings.firmAddress}</p>
                            <p class="text-[10px] font-black text-slate-800">M: +91 ${settings.firmMobile} • ${settings.firmEmail}</p>
                          </div>
                        </div>
                      </div>
                    </td>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>
                      <div class="grid grid-cols-2 gap-10 mb-10">
                        <div>
                           <h4 class="text-[10px] font-black uppercase text-slate-400 mb-1">Received From:</h4>
                           <p class="text-lg font-black uppercase">${previewPayment.clientName}</p>
                        </div>
                        <div class="text-right">
                           <h4 class="text-[10px] font-black uppercase text-slate-400 mb-1">Payment Info:</h4>
                           <p class="text-[10px] font-bold uppercase"><span class="text-slate-400">Date:</span> ${previewPayment.date.split('-').reverse().join('-')}</p>
                           <p class="text-[10px] font-bold uppercase"><span class="text-slate-400">Mode:</span> ${previewPayment.mode}</p>
                           <p class="text-[10px] font-bold uppercase"><span class="text-slate-400">Inv:</span> ${previewPayment.invoiceNo || 'Direct'}</p>
                        </div>
                      </div>

                      <table class="w-full">
                         <thead>
                            <tr class="bg-slate-900 text-white">
                               <th class="px-3 py-2 text-[10px] font-black uppercase text-left w-[40px]">S.No</th>
                               <th class="px-3 py-2 text-[10px] font-black uppercase text-left">Description of Settlement</th>
                               <th class="px-3 py-2 text-[10px] font-black uppercase text-right w-[150px]">Amount</th>
                            </tr>
                         </thead>
                         <tbody class="divide-y divide-slate-200">
                            ${previewPayment.originalItems ? previewPayment.originalItems.map((item, i) => `
                               <tr>
                                  <td class="px-3 py-4 text-xs font-bold text-slate-400">${i + 1}</td>
                                  <td class="px-3 py-4 text-xs font-black uppercase">${item.description}</td>
                                  <td class="px-3 py-4 text-xs font-black text-right">₹${item.amount.toLocaleString()}</td>
                               </tr>
                            `).join('') : `
                               <tr>
                                  <td class="px-3 py-4 text-xs font-bold text-slate-400">1</td>
                                  <td class="px-3 py-4 text-xs font-black uppercase">Consolidated Professional Fees</td>
                                  <td class="px-3 py-4 text-xs font-black text-right">₹${previewPayment.amount.toLocaleString()}</td>
                               </tr>
                            `}
                         </tbody>
                      </table>
                    </td>
                  </tr>
                </tbody>
                <tfoot>
                  <tr>
                    <td>
                       <div class="mt-10 pt-10 border-t">
                          <div class="flex justify-end mb-16">
                             <div class="w-64 bg-emerald-50 p-4 rounded-xl border border-emerald-100 text-right">
                                <p class="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Net Received</p>
                                <p class="text-2xl font-black text-emerald-800 uppercase">₹${previewPayment.amount.toLocaleString()}</p>
                             </div>
                          </div>
                          <div class="flex justify-between items-end">
                             <div class="max-w-[400px]">
                                <p class="text-[9px] font-medium text-slate-400 leading-relaxed">This is an electronically generated acknowledgment. No physical signature required.</p>
                             </div>
                             <div class="text-right">
                                ${settings.firmSignature ? `<img src="${settings.firmSignature}" class="h-12 ml-auto mb-2 opacity-90 mix-blend-multiply" />` : ''}
                                <p class="text-[9px] font-black uppercase border-t border-slate-900 pt-1.5 px-4">Finance Department</p>
                             </div>
                          </div>
                       </div>
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
    }
  };

  const handleWhatsAppShare = async (pay: PaymentRecord) => {
    const text = `*Payment Receipt Confirmation*\n\nFirm: ${settings?.firmName}\nGSTIN: ${settings?.firmGstin}\nClient: ${pay.clientName}\nInv No: ${pay.invoiceNo || 'Direct Payment'}\nAmount: ₹${pay.amount.toLocaleString()}\nDate: ${pay.date.split('-').reverse().join('-')}\nMode: ${pay.mode}\n\n*Thank you for the payment!*`;

    if (navigator.share) {
      try { await navigator.share({ title: 'Payment Receipt', text }); } 
      catch (err) { window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank'); }
    } else {
      window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden pb-10">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Collections</p>
            <p className="text-xl font-black text-slate-900 leading-none">₹{stats.total.toLocaleString()}</p>
          </div>
          <div className="flex items-center gap-4 border-l border-slate-100 pl-6">
             <div className="text-center">
                <p className="text-[8px] font-black text-emerald-500 uppercase">Online/UPI</p>
                <p className="text-xs font-black">₹{stats.online.toLocaleString()}</p>
             </div>
             <div className="text-center border-l border-slate-100 pl-4">
                <p className="text-[8px] font-black text-blue-500 uppercase">Cheque</p>
                <p className="text-xs font-black">₹{stats.cheque.toLocaleString()}</p>
             </div>
          </div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search Client, Inv No or Ref..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-emerald-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-emerald-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
