];

const DueDateSetting: React.FC = () => {
  const [selectedYear, setSelectedYear] = useState(YEARS[0]);
  const [selectedReturn, setSelectedReturn] = useState(RETURN_CATEGORIES[0].id);
  const [isLoading, setIsLoading] = useState(true);
  const [dates, setDates] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);

  const STORAGE_KEY = 'clientify_global_compliance_dates_v1';

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) setDates(JSON.parse(saved));
    setIsLoading(false);
  }, []);

  const handleDateChange = (period: string, value: string) => {
    const key = `${selectedReturn}_${selectedYear}_${period}`;
    setDates(prev => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    setIsSaving(true);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(dates));

    // Propagate legacy data for immediate portfolio sync
    const currentCat = RETURN_CATEGORIES.find(c => c.id === selectedReturn);
    if (currentCat?.type === 'monthly') {
       FY_MONTHS.forEach(m => {
          const key = `${selectedReturn}_${selectedYear}_${m}`;
          if (dates[key]) {
             if (selectedReturn === 'monthly_r1') {
                const legacy = JSON.parse(localStorage.getItem('clientify_monthly_due_dates_v1') || '{}');
                localStorage.setItem('clientify_monthly_due_dates_v1', JSON.stringify({...legacy, [`${selectedYear}_${m}`]: dates[key]}));
             }
          }
       });
    }

    setTimeout(() => setIsSaving(false), 800);
  };

  const currentCategory = RETURN_CATEGORIES.find(c => c.id === selectedReturn);

  const periodsToDisplay = useMemo(() => {
    if (currentCategory?.type === 'monthly') return FY_MONTHS;
    if (currentCategory?.type === 'quarterly') return FY_QUARTERS;
    return ['Full Year'];
  }, [currentCategory]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500 max-w-5xl mx-auto w-full overflow-hidden">

      <div className="flex flex-col md:flex-row items-center justify-between bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm shrink-0 gap-4">
        <div className="flex flex-wrap items-center gap-4">
           <div>
              <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight leading-none">Due Date Hub</h2>
              <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mt-1">Unified Compliance Calendar</p>
           </div>
           <div className="h-10 w-[1px] bg-slate-100 hidden md:block" />
           <div className="flex gap-2">
              <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-[11px] font-black uppercase outline-none cursor-pointer">
                {YEARS.map(y => <option key={y} value={y}>FY {y}</option>)}
              </select>
              <select value={selectedReturn} onChange={e => setSelectedReturn(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-[11px] font-black uppercase outline-none cursor-pointer min-w-[200px]">
                {RETURN_CATEGORIES.map(cat => <option key={cat.id} value={cat.id}>{cat.label}</option>)}
              </select>
           </div>
        </div>
        <button onClick={handleSave} disabled={isSaving}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-10 h-12 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs disabled:opacity-50 w-full md:w-auto">
          {isSaving ? 'Syncing...' : 'Save Dates'}
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-y-auto no-scrollbar p-10">
         <div className="max-w-2xl mx-auto">
            <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 border-b border-slate-100 pb-4 mb-8">
               Setting Deadlines for: <span className="text-indigo-600 font-black">{currentCategory?.label}</span>
            </h3>

            <div className="space-y-4">
               {periodsToDisplay.map((period) => (
                  <div key={period} className="flex items-center justify-between p-6 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-white hover:shadow-xl transition-all group border-l-4 hover:border-l-indigo-600">
                     <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Period</p>
                        <p className="text-sm font-black text-slate-700 uppercase">{period}</p>
                     </div>
                     <div className="flex flex-col items-end">
                        <label className="text-[9px] font-black text-indigo-400 uppercase mb-1">Due Date</label>
                        <input 
                          type="date" 
                          value={dates[`${selectedReturn}_${selectedYear}_${period}`] || ''} 
                          onChange={e => handleDateChange(period, e.target.value)}
                          className="bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-black uppercase outline-none focus:ring-4 focus:ring-indigo-100 transition-all cursor-pointer shadow-sm"
                        />
                     </div>
                  </div>
               ))}
            </div>
         </div>
      </div>

      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex items-center justify-between shadow-2xl relative overflow-hidden shrink-0">
         <div className="absolute -top-10 -right-10 h-40 w-40 bg-indigo-500/20 rounded-full blur-3xl" />
         <div>
            <h4 className="text-lg font-black uppercase tracking-tight">Staff Update</h4>
            <p className="text-slate-400 text-sm font-medium mt-1">Standardizing these dates ensures all automated client reminders are sent exactly on time.</p>
         </div>
         <div className="h-12 w-12 rounded-xl bg-white/10 flex items-center justify-center text-indigo-400">
            <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
         </div>
      </div>
    </div>
  );
};

