import React, { useState, useEffect, useMemo, useRef } from 'react';
import { InvoiceRecord, Client, InvoiceSettings } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';

interface InvoicesProps {
  onViewChange?: (view: string, extra?: any) => void;
}

const Invoices: React.FC<InvoicesProps> = ({ onViewChange }) => {
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Pending' | 'Sent'>('All');
  const [isFilterOpen, setIsFilterOpen] = useState(false);

  const [settings, setSettings] = useState<InvoiceSettings | null>(null);

  // Settlement Modal States
  const [settlingInvoice, setSettlingInvoice] = useState<InvoiceRecord | null>(null);
  const [payDate, setPayDate] = useState(new Date().toISOString().split('T')[0]);
  const [payMode, setPayMode] = useState<'Cash' | 'Online' | 'Cheque' | 'UPI'>('Online');
  const [chequeNo, setChequeNo] = useState('');

  // PDF Preview State
  const [previewInvoice, setPreviewInvoice] = useState<InvoiceRecord | null>(null);
  const printRef = useRef<HTMLDivElement>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    const [invs, sets] = await Promise.all([
      mockBackend.getInvoices(),
      mockBackend.getInvoiceSettings()
    ]);
    setInvoices(invs);
    setSettings(sets);
    setIsLoading(false);
  };

  useEffect(() => { fetchAll(); }, []);

  const filteredInvoices = useMemo(() => {
    const s = search.toLowerCase();
    let list = invoices.filter(i => 
      i.invoiceNo.toLowerCase().includes(s) || 
      i.clientName.toLowerCase().includes(s)
    ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (statusFilter !== 'All') {
      list = list.filter(i => i.status === statusFilter);
    }
    return list;
  }, [invoices, search, statusFilter]);

  const handleReceiveConfirm = async () => {
    if (!settlingInvoice) return;
    await mockBackend.migrateToPayment(settlingInvoice.id, {
      date: payDate,
      mode: payMode,
      chequeNo: payMode === 'Cheque' ? chequeNo : undefined
    });
    setSettlingInvoice(null);
    fetchAll();
  };

  const handleWhatsApp = (inv: InvoiceRecord) => {
    const text = `*Invoice from ${settings?.firmName || 'Vault'}*\n\nInv No: ${inv.invoiceNo}\nDate: ${inv.date.split('-').reverse().join('-')}\nAmount: ₹${inv.totalAmount.toLocaleString()}\nDue Date: ${inv.dueDate.split('-').reverse().join('-')}\n\nKindly settle the same. Thank you!`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handlePrint = () => {
    const printContent = printRef.current;
    if (!printContent) return;

    const windowUrl = 'about:blank';
    const printWindow = window.open(windowUrl, '_blank', 'width=800,height=900');

    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Invoice - ${previewInvoice?.invoiceNo}</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <style>
              @media print {
                @page { size: A4; margin: 15mm; }
                body { padding: 0; margin: 0; font-family: sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .no-print { display: none; }

                /* Repeating header logic */
                thead { display: table-header-group; }
                tfoot { display: table-footer-group; }

                tr { break-inside: avoid; }
                table { width: 100%; border-collapse: collapse; }

                .footer-space { height: 10px; }
              }
              body { color: #0f172a; }
            </style>
          </head>
          <body onload="setTimeout(() => { window.print(); window.close(); }, 700)">
            <div class="p-4">
              <table class="w-full">
                <thead>
                  <tr>
                    <td>
                      <!-- REPEATING HEADER CONTENT -->
                      <div class="border-b-2 border-slate-900 pb-6 mb-6">
                        <div class="flex justify-between items-start">
                          <div class="space-y-3">
                            ${settings?.firmLogo ? `<img src="${settings.firmLogo}" class="h-16 object-contain" />` : ''}
                            <h1 class="text-3xl font-black uppercase tracking-tight">Invoice</h1>
                            <p class="text-slate-500 font-bold uppercase text-sm">${previewInvoice?.invoiceNo}</p>
                          </div>
                          <div class="text-right space-y-1 max-w-[350px]">
                            <p class="text-lg font-black uppercase">${settings?.firmName}</p>
                            <p class="text-[9px] font-black text-indigo-600 font-mono">GSTIN: ${settings?.firmGstin}</p>
                            <p class="text-[9px] font-bold text-slate-500 uppercase whitespace-pre-wrap leading-relaxed">${settings?.firmAddress}</p>
                            <p class="text-[10px] font-black text-slate-800">M: +91 ${settings?.firmMobile} • ${settings?.firmEmail}</p>
                          </div>
                        </div>
                        <div class="grid grid-cols-2 gap-10 mt-8">
                          <div>
                            <h4 class="text-[10px] font-black uppercase text-slate-400 mb-1">Bill To:</h4>
                            <p class="text-lg font-black uppercase">${previewInvoice?.clientName}</p>
                            <p class="text-[9px] font-medium text-slate-500 uppercase">${previewInvoice?.miscAddress || 'Registered Office'}</p>
                          </div>
                          <div class="text-right">
                             <h4 class="text-[10px] font-black uppercase text-slate-400 mb-1">Timeline:</h4>
                             <p class="text-[10px] font-bold"><span class="text-slate-400 uppercase">Date:</span> ${previewInvoice?.date.split('-').reverse().join('-')}</p>
                             <p class="text-[10px] font-bold"><span class="text-slate-400 uppercase">Due:</span> ${previewInvoice?.dueDate.split('-').reverse().join('-')}</p>
                          </div>
                        </div>
                      </div>
                    </td>
                  </tr>
                </thead>

                <tbody>
                  <tr>
                    <td>
                      <table class="w-full">
                        <thead>
                          <tr class="bg-slate-900 text-white">
                            <th class="px-3 py-2 text-[10px] font-black uppercase text-left w-[40px]">S.No</th>
                            <th class="px-3 py-2 text-[10px] font-black uppercase text-left">Description of Service</th>
                            <th class="px-3 py-2 text-[10px] font-black uppercase text-right w-[60px]">Qty</th>
                            <th class="px-3 py-2 text-[10px] font-black uppercase text-right w-[100px]">Rate</th>
                            ${settings?.isGstEnabled ? '<th class="px-3 py-2 text-[10px] font-black uppercase text-right w-[60px]">GST%</th>' : ''}
                            <th class="px-3 py-2 text-[10px] font-black uppercase text-right w-[110px]">Amount</th>
                          </tr>
                        </thead>
                        <tbody class="divide-y divide-slate-200">
                          ${previewInvoice?.items.map((item, i) => `
                            <tr>
                              <td class="px-3 py-4 text-xs font-bold text-slate-400">${i + 1}</td>
                              <td class="px-3 py-4 text-xs font-black uppercase">${item.description}</td>
                              <td class="px-3 py-4 text-xs font-bold text-right">${item.quantity}</td>
                              <td class="px-3 py-4 text-xs font-bold text-right">₹${item.rate.toLocaleString()}</td>
                              ${settings?.isGstEnabled ? `<td class="px-3 py-4 text-xs font-bold text-right">${item.taxRate}%</td>` : ''}
                              <td class="px-3 py-4 text-xs font-black text-right">₹${item.amount.toLocaleString()}</td>
                            </tr>
                          `).join('')}
                        </tbody>
                      </table>
                    </td>
                  </tr>
                </tbody>

                <tfoot>
                  <tr>
                    <td>
                      <!-- SUMMARY BLOCK - Only appears at the very end of all pages -->
                      <div class="mt-10 border-t pt-10">
                        <div class="flex justify-between items-start">
                          <div class="bg-slate-50 p-4 rounded-xl border border-slate-100 max-w-[300px]">
                            <h4 class="text-[9px] font-black uppercase text-slate-400 mb-2 tracking-widest">Bank Instructions:</h4>
                            <div class="space-y-1 text-[10px] font-bold">
                              <p>${settings?.bankName}</p>
                              <p>A/c: ${settings?.accountNo}</p>
                              <p>IFSC: ${settings?.ifsc}</p>
                            </div>
                            ${settings?.upiId ? `
                              <div class="mt-4 pt-4 border-t border-slate-200 flex items-center gap-3">
                                <img src="https://api.qrserver.com/v1/create-qr-code/?size=60x60&data=upi://pay?pa=${settings.upiId}&pn=${encodeURIComponent(settings.firmName)}&am=${previewInvoice?.totalAmount}&cu=INR" class="h-14 w-14" />
                                <p class="text-[8px] font-black text-slate-400 uppercase leading-tight">Scan for<br/>Direct Pay</p>
                              </div>
                            ` : ''}
                          </div>

                          <div class="w-64 space-y-2">
                             <div class="flex justify-between text-slate-500 font-bold text-[10px] uppercase"><span>Subtotal</span><span>₹${previewInvoice?.subTotal.toLocaleString()}</span></div>
                             ${settings?.isGstEnabled ? `<div class="flex justify-between text-slate-500 font-bold text-[10px] uppercase border-b border-slate-100 pb-2"><span>Aggregate GST</span><span>₹${previewInvoice?.totalTax.toLocaleString()}</span></div>` : ''}
                             <div class="flex justify-between text-xl font-black uppercase pt-1 text-slate-900"><span>Total Due</span><span>₹${previewInvoice?.totalAmount.toLocaleString()}</span></div>
                          </div>
                        </div>

                        <div class="mt-12 flex justify-between items-end">
                           <div class="max-w-[400px]">
                              <p class="text-[9px] font-medium text-slate-400 leading-relaxed uppercase whitespace-pre-wrap">${settings?.terms}</p>
                           </div>
                           <div class="text-right">
                              ${settings?.firmSignature ? `<img src="${settings.firmSignature}" class="h-12 ml-auto mb-2 opacity-90 mix-blend-multiply" />` : ''}
                              <p class="text-[9px] font-black uppercase border-t border-slate-900 pt-1.5 px-4">Authorized Signatory</p>
                           </div>
                        </div>
                      </div>
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden pb-10">

      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Bills</p>
            <p className="text-xl font-black text-slate-900 leading-none">{invoices.length}</p>
          </div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search by Invoice No or Client..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex gap-2">
          <div className="relative">
            <button onClick={() => setIsFilterOpen(!isFilterOpen)} className="h-11 px-4 flex items-center gap-2 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-black uppercase text-slate-500 hover:bg-slate-100">
               Filter: {statusFilter} <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isFilterOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white border border-slate-200 rounded-xl shadow-2xl z-50 p-1 animate-in zoom-in-95">
                {['All', 'Pending', 'Sent'].map(f => (
                  <button key={f} onClick={() => { setStatusFilter(f as any); setIsFilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${statusFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                ))}
              </div>
            )}
          </div>
          <button onClick={() => onViewChange?.('admin-invoice-setting')} className="h-11 w-11 flex items-center justify-center bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-all shadow-sm">
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
          </button>
          <button onClick={() => onViewChange?.('admin-add-invoice')} className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Create Invoice
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Inv. No.</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Client</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Service</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Amount</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Due Date</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-center w-[140px]">Status</th>
                <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[180px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredInvoices.length === 0 ? (
                <tr><td colSpan={9} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No billing records found</td></tr>
              ) : (
                filteredInvoices.map((inv, idx) => (
                  <tr key={inv.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-6 py-6 text-[12px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
